base = json.load(open("src/lib/ar-en-map.json", encoding="utf-8"))
expected_before = len(base)
added = skipped = 0
for lang, p in PATHS.items():
    d = json.load(open(p, encoding="utf-8"))
    for ar, tr in NEW[lang].items():
        if ar in d:
            if d[ar] == tr:
                skipped += 1
            continue
        d[ar] = tr
    with open(p, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2, separators=(", ", ": "))
        f.write("\n")
    print(f"{lang}: {len(d)} keys")

after = json.load(open("src/lib/ar-en-map.json", encoding="utf-8"))
print(f"\nnew keys this run: {len(NEW['en'])} (existing/skipped: {skipped // 5})")
print(f"en total: {expected_before} -> {len(after)}")
